This implementation uses a classic **Inverted Index** for efficient lookups and a **TF-IDF (Term Frequency-Inverse Document Frequency)** algorithm for ranking search results. This code is self-contained and can be integrated as the backend for the `/v1beta/search` endpoint defined previously.

### Search Engine Core Logic

This module provides the fundamental building blocks for indexing documents and performing ranked searches [file:parallel.txt]. It avoids external search libraries to adhere to the "from-scratch" requirement.

**`app/core/search_engine.py`**
```python
import re
import math
from collections import defaultdict
from typing import List, Dict, NamedTuple

class Document(NamedTuple):
    id: int
    url: str
    title: str
    content: str

def tokenize(text: str) -> List[str]:
    return re.findall(r'\b\w+\b', text.lower())

class SearchEngine:
    def __init__(self):
        self.documents: Dict[int, Document] = {}
        self.inverted_index: Dict[str, List[int]] = defaultdict(list)
        self.doc_term_freqs: Dict[int, Dict[str, int]] = defaultdict(lambda: defaultdict(int))
        self.doc_count = 0

    def index_documents(self, documents: List[Document]):
        for doc in documents:
            if doc.id in self.documents:
                continue

            self.documents[doc.id] = doc
            self.doc_count += 1

            terms = tokenize(doc.content)
            doc_len = len(terms)

            for term in terms:
                self.doc_term_freqs[doc.id][term] += 1

            for term in self.doc_term_freqs[doc.id]:
                if doc.id not in self.inverted_index[term]:
                    self.inverted_index[term].append(doc.id)

    def _calculate_tf(self, term: str, doc_id: int) -> float:
        term_count = self.doc_term_freqs[doc_id].get(term, 0)
        total_terms = sum(self.doc_term_freqs[doc_id].values())
        if total_terms == 0:
            return 0.0
        return term_count / total_terms

    def _calculate_idf(self, term: str) -> float:
        doc_freq = len(self.inverted_index.get(term, []))
        if doc_freq == 0:
            return 0.0
        return math.log(self.doc_count / doc_freq)

    def search(self, query: str, top_k: int = 10) -> List[Dict]:
        query_terms = tokenize(query)

        candidate_docs = set()
        for term in query_terms:
            doc_ids = self.inverted_index.get(term, [])
            candidate_docs.update(doc_ids)

        scores = defaultdict(float)
        for doc_id in candidate_docs:
            for term in query_terms:
                tf = self._calculate_tf(term, doc_id)
                idf = self._calculate_idf(term)
                scores[doc_id] += tf * idf

        sorted_docs = sorted(scores.items(), key=lambda item: item[1], reverse=True)

        results = []
        for doc_id, score in sorted_docs[:top_k]:
            doc = self.documents[doc_id]
            results.append({
                "title": doc.title,
                "url": doc.url,
                "snippet": self._generate_snippet(doc.content, query_terms),
                "score": score
            })
        return results

    def _generate_snippet(self, content: str, query_terms: List[str], length: int = 150) -> str:
        first_match_pos = -1
        for term in query_terms:
            try:
                pos = content.lower().index(term)
                if first_match_pos == -1 or pos < first_match_pos:
                    first_match_pos = pos
            except ValueError:
                continue

        if first_match_pos == -1:
            first_match_pos = 0

        start = max(0, first_match_pos - length // 2)
        end = start + length
        snippet = content[start:end]

        if start > 0:
            snippet = "... " + snippet
        if end < len(content):
            snippet = snippet + " ..."

        return snippet

```
This implementation provides a solid foundation. You can integrate it into the `search.py` endpoint by initializing the `SearchEngine`, populating it with crawled documents, and calling the `search` method with the user's query.
